package cn.jingyu.deepseek;
import android.content.Context;import android.graphics.*;import android.graphics.pdf.PdfDocument;import android.text.*;import android.text.style.*;import java.io.*;import java.util.*;import java.util.regex.*;import org.json.*;import org.scilab.forge.jlatexmath.*;import ru.noties.jlatexmath.awt.AndroidGraphics2D;

/** Vector PDF publishing. Long cells split across pages without dropping text. */
final class PdfWriter {
 private final PdfDocument pdf=new PdfDocument();private final DocumentLayout model;private PdfDocument.Page page;private Canvas canvas;private float y;private int pageNumber;private final int accent,bottom;private final TextPaint paint=new TextPaint(3);private Typeface font;private static final int LEFT=52,TOP=54;
 private PdfWriter(Context context,JSONObject spec)throws Exception {model=new DocumentLayout(spec);accent=Color.parseColor("#"+model.accent);bottom=model.pageHeight-56;font=Typeface.create("sans-serif",0);if(model.style.equals("formal"))try{font=Typeface.createFromAsset(context.getAssets(),"fonts/NotoSerifSC.ttf");}catch(Exception ignored){font=Typeface.create("serif",0);}}
 static void write(Context context,OutputStream out,JSONObject spec)throws Exception {ru.noties.jlatexmath.JLatexMathAndroid.init(context.getApplicationContext());PdfWriter w=new PdfWriter(context,spec);try{w.newPage();w.document();w.finish();w.pdf.writeTo(out);}finally{w.finish();w.pdf.close();}}
 private void finish(){if(page!=null){pdf.finishPage(page);page=null;}}
 private void newPage()throws IOException {finish();if(++pageNumber>300)throw new IOException("PDF超过300页，请拆分内容。");page=pdf.startPage(new PdfDocument.PageInfo.Builder(model.pageWidth,model.pageHeight,pageNumber).create());canvas=page.getCanvas();canvas.drawColor(Color.WHITE);if(model.numbers){Paint p=new Paint(3);p.setColor(0xff72818A);p.setTextSize(9);p.setTextAlign(Paint.Align.CENTER);canvas.drawText(String.valueOf(pageNumber),model.pageWidth/2f,model.pageHeight-28,p);}y=TOP;}
 private void ensure(float height)throws IOException {if(y+height>bottom&&y>TOP)newPage();}
 private void document()throws Exception {boolean title=false;boolean hasTitle=!model.blocks.isEmpty()&&model.blocks.get(0).kind.equals("heading")&&model.blocks.get(0).level==1;if(!hasTitle){paragraph(model.title,23,true,"title",0,"");intro();title=true;}
  for(DocumentLayout.Block b:model.blocks){switch(b.kind){case "heading":ensure(b.level==1?90:70);y+=b.level==1?0:10;paragraph(b.text,b.level==1?23:b.level==2?16:13,true,b.level==1?"title":"heading",0,"");if(b.level==1&&!title){intro();title=true;}break;
   case "math":math(b.text);break;case "table":table(b);break;case "break":if(y>TOP)newPage();break;
   case "code":paragraph(b.text,10,false,"code",0,"");break;case "quote":paragraph(b.text,model.font,false,"quote",0,"");break;
   case "list":paragraph(b.text,model.font,false,"list",b.level,b.ordered?b.start+".":"•");break;
   default:paragraph(b.text,model.font,false,"body",0,"");}
  }
 }
 private void intro()throws Exception {if(!model.subtitle.isEmpty())paragraph(model.subtitle,11.5f,false,"subtitle",0,"");if(!model.toc)return;int n=0;for(DocumentLayout.Block b:model.blocks)if(b.kind.equals("heading")&&b.level>1&&b.level<=3)n++;if(n==0)return;paragraph("目录",14,true,"heading",0,"");for(DocumentLayout.Block b:model.blocks)if(b.kind.equals("heading")&&b.level>1&&b.level<=3)paragraph(b.text,model.font,false,"body",b.level-2,"");if(y>TOP)newPage();}
 private StaticLayout layout(CharSequence text,float size,int width,String align){TextPaint p=new TextPaint(paint);p.setTextSize(size);p.setColor(0xff243239);p.setTypeface(font);return StaticLayout.Builder.obtain(text,0,text.length(),p,Math.max(12,width)).setAlignment(align.equals("right")?Layout.Alignment.ALIGN_OPPOSITE:align.equals("center")?Layout.Alignment.ALIGN_CENTER:Layout.Alignment.ALIGN_NORMAL).setLineSpacing(size<11?2:3,1.12f).setIncludePad(false).setBreakStrategy(Layout.BREAK_STRATEGY_SIMPLE).build();}
 private void paragraph(String raw,float size,boolean bold,String kind,int level,String bullet)throws Exception {boolean code=kind.equals("code"),quote=kind.equals("quote");SpannableStringBuilder s=code?new SpannableStringBuilder(raw):inline(raw);int color=kind.equals("title")?0xff17272E:kind.equals("subtitle")?0xff697881:accent;if(bold){s.setSpan(new StyleSpan(1),0,s.length(),33);s.setSpan(new ForegroundColorSpan(color),0,s.length(),33);}if(kind.equals("subtitle"))s.setSpan(new ForegroundColorSpan(color),0,s.length(),33);if(code)s.setSpan(new TypefaceSpan("monospace"),0,s.length(),33);
  int inset=code||quote?12:!bullet.isEmpty()?20+level*15:level*15,width=model.bodyWidth-inset-(code||quote?12:0);StaticLayout text=layout(s,size,width,"left");int line=0;boolean label=false;
  while(line<text.getLineCount()){ensure(size*2+10);int first=line,start=text.getLineTop(first);while(line<text.getLineCount()&&y+text.getLineBottom(line)-start+6<=bottom)line++;if(line==first)throw new IOException("段落行高超过页面可用高度。");int height=text.getLineBottom(line-1)-start;if(code||quote){Paint bg=new Paint();bg.setColor(code?0xffF1F4F6:0xffF0F5F7);canvas.drawRoundRect(LEFT,y-3,LEFT+model.bodyWidth,y+height+5,3,3,bg);if(quote){bg.setColor(accent);canvas.drawRect(LEFT,y-3,LEFT+2,y+height+5,bg);}}
   if(!bullet.isEmpty()&&!label){Paint p=new Paint(3);p.setTextSize(size);p.setColor(accent);canvas.drawText(bullet,LEFT+level*15,y+text.getLineBaseline(first)-start,p);label=true;}
   canvas.save();canvas.clipRect(LEFT+inset,y,LEFT+inset+width,y+height);canvas.translate(LEFT+inset,y-start);text.draw(canvas);canvas.restore();y+=height+9;if(line<text.getLineCount())newPage();}
 }

 private SpannableStringBuilder inline(String raw){SpannableStringBuilder out=new SpannableStringBuilder();String lastLink="";for(DocumentInline.Run r:DocumentInline.parse(raw)){if(!lastLink.isEmpty()&&!lastLink.equals(r.link))out.append(" ("+lastLink+")");int start=out.length();out.append(r.text);if(r.bold||r.italic)out.setSpan(new StyleSpan(r.bold&&r.italic?3:r.bold?1:2),start,out.length(),33);if(r.code)out.setSpan(new TypefaceSpan("monospace"),start,out.length(),33);if(!r.link.isEmpty())out.setSpan(new ForegroundColorSpan(accent),start,out.length(),33);if(r.math)try{out.setSpan(new FormulaSpan(r.text,model.font),start,out.length(),33);}catch(Exception e){throw new IllegalArgumentException("行内公式无法排版，请检查LaTeX："+r.text,e);}lastLink=r.link;}if(!lastLink.isEmpty())out.append(" ("+lastLink+")");return out;}
 private void math(String formula)throws Exception {TeXIcon icon;synchronized(TeXFormula.class){icon=new TeXFormula(formula).createTeXIcon(TeXConstants.STYLE_DISPLAY,model.font+3);}float scale=Math.min(1f,model.bodyWidth/(float)Math.max(1,icon.getIconWidth()));scale=Math.min(scale,(bottom-TOP-24f)/Math.max(1,icon.getIconHeight()));float h=icon.getIconHeight()*scale;ensure(h+24);canvas.save();canvas.translate(LEFT+(model.bodyWidth-icon.getIconWidth()*scale)/2,y+8);canvas.scale(scale,scale);AndroidGraphics2D g=new AndroidGraphics2D();g.setCanvas(canvas);icon.paintIcon(null,g,0,0);canvas.restore();y+=h+24;}
 private StaticLayout[] rowLayouts(String[] row,int[] widths,String[] aligns,boolean header){StaticLayout[] result=new StaticLayout[row.length];for(int c=0;c<row.length;c++){SpannableStringBuilder value=inline(row[c]);if(header){value.setSpan(new StyleSpan(1),0,value.length(),33);value.setSpan(new ForegroundColorSpan(Color.WHITE),0,value.length(),33);}result[c]=layout(value,Math.max(10,model.font-.5f),widths[c]-16,aligns[c]);}return result;}
 private float rowHeight(StaticLayout[] cells){int max=0;for(StaticLayout t:cells)max=Math.max(max,t.getHeight());return max+16;}
 private void drawSlice(StaticLayout[] cells,int[] widths,int[] offsets,int[] ends,float height,boolean header,boolean stripe){Paint p=new Paint();p.setColor(header?accent:stripe?0xffF2F6F8:Color.WHITE);canvas.drawRect(LEFT,y,LEFT+model.bodyWidth,y+height,p);int x=LEFT;for(int c=0;c<cells.length;c++){if(ends[c]>offsets[c]){StaticLayout t=cells[c];int start=t.getLineTop(offsets[c]),h=t.getLineBottom(ends[c]-1)-start;canvas.save();canvas.clipRect(x+8,y+8,x+widths[c]-8,y+8+h);canvas.translate(x+8,y+8-start);t.draw(canvas);canvas.restore();}x+=widths[c];}p.setColor(0xffDBE3E7);p.setStrokeWidth(.5f);canvas.drawLine(LEFT,y+height,LEFT+model.bodyWidth,y+height,p);y+=height;}
 private void header(StaticLayout[] cells,int[] widths)throws Exception {float h=rowHeight(cells);if(h>Math.min(150,(bottom-TOP)/3f))throw new IOException("表头过长，请缩短列名或转为横向页面。");int[] first=new int[cells.length],last=new int[cells.length];for(int c=0;c<last.length;c++)last[c]=cells[c].getLineCount();drawSlice(cells,widths,first,last,h,true,false);}
 private void table(DocumentLayout.Block b)throws Exception {int[] widths=DocumentLayout.widths(b.rows,model.bodyWidth);StaticLayout[] head=rowLayouts(b.rows.get(0),widths,b.align,true);float hh=rowHeight(head);ensure(hh+40);header(head,widths);
  for(int r=1;r<b.rows.size();r++){StaticLayout[] cells=rowLayouts(b.rows.get(r),widths,b.align,false);float full=rowHeight(cells);if(full+hh<=bottom-TOP&&y+full>bottom){newPage();header(head,widths);}int[] offsets=new int[cells.length];boolean remaining=true;
   while(remaining){if(bottom-y<36){newPage();header(head,widths);}int[] ends=offsets.clone();float height=0;boolean advanced=false;for(int c=0;c<cells.length;c++){StaticLayout t=cells[c];if(offsets[c]>=t.getLineCount())continue;int start=t.getLineTop(offsets[c]);while(ends[c]<t.getLineCount()&&t.getLineBottom(ends[c])-start+16<=bottom-y)ends[c]++;if(ends[c]>offsets[c]){advanced=true;height=Math.max(height,t.getLineBottom(ends[c]-1)-start+16);}}
    if(!advanced){if(y<=TOP+hh+1)throw new IOException("表格单元格行高超过页面，请拆分内容。");newPage();header(head,widths);continue;}drawSlice(cells,widths,offsets,ends,height,false,r%2==0);offsets=ends;remaining=false;for(int c=0;c<cells.length;c++)if(offsets[c]<cells[c].getLineCount())remaining=true;if(remaining){newPage();header(head,widths);}
   }
  }y+=12;
 }
 private static final class FormulaSpan extends ReplacementSpan {final TeXIcon icon;FormulaSpan(String tex,float size)throws Exception{synchronized(TeXFormula.class){icon=new TeXFormula(tex).createTeXIcon(TeXConstants.STYLE_TEXT,size);}}public int getSize(Paint p,CharSequence t,int start,int end,Paint.FontMetricsInt fm){if(fm!=null){fm.ascent=-icon.getIconHeight()+icon.getIconDepth();fm.descent=icon.getIconDepth();fm.top=fm.ascent;fm.bottom=fm.descent;}return icon.getIconWidth();}public void draw(Canvas c,CharSequence t,int start,int end,float x,int top,int baseline,int bottom,Paint p){c.save();c.translate(x,baseline-icon.getIconHeight()+icon.getIconDepth());AndroidGraphics2D g=new AndroidGraphics2D();g.setCanvas(c);icon.paintIcon(null,g,0,0);c.restore();}}
}
